// Shared preloader for the hero frame sequence (generated by scripts/make-hero-frames.py).
// The loader reports its progress; the hero draws from the same Image objects.
export const FRAME_COUNT = 90;
export const ASSEMBLED = 49;

const frameSrc = (index: number) => `/hero/frames/hero_${String(index).padStart(3, "0")}.webp`;

let frames: HTMLImageElement[] | null = null;
let settled = 0;
const listeners = new Set<(progress: number) => void>();

export function getHeroFrames() {
  if (frames) return frames;
  frames = Array.from({ length: FRAME_COUNT }, (_, index) => {
    const frame = new Image();
    const done = () => {
      settled += 1;
      listeners.forEach((listener) => listener(settled / FRAME_COUNT));
    };
    frame.addEventListener("load", done, { once: true });
    frame.addEventListener("error", done, { once: true });
    frame.src = frameSrc(index);
    return frame;
  });
  return frames;
}

export function onHeroFramesProgress(listener: (progress: number) => void) {
  getHeroFrames();
  listeners.add(listener);
  listener(settled / FRAME_COUNT);
  return () => {
    listeners.delete(listener);
  };
}
